import csv
import unittest

from handoff_demo.export import parse_export_row


class ExportHiddenTests(unittest.TestCase):
    def test_quoted_delimiters_and_escaped_quotes(self):
        self.assertEqual(parse_export_row('alpha;"beta;gamma";delta'), ["alpha", "beta;gamma", "delta"])
        self.assertEqual(parse_export_row('"say ""hi""";ok'), ['say "hi"', "ok"])

    def test_empty_fields_and_spaces_are_data(self):
        self.assertEqual(parse_export_row(';"";  keep  ;'), ["", "", "  keep  ", ""])
        self.assertEqual(parse_export_row(""), [])

    def test_quoted_newline_is_one_field(self):
        self.assertEqual(parse_export_row('"first\nsecond";ok'), ["first\nsecond", "ok"])

    def test_multiple_records_and_broken_quotes_fail(self):
        with self.assertRaises((ValueError, csv.Error)):
            parse_export_row("a;b\nc;d")
        with self.assertRaises((ValueError, csv.Error)):
            parse_export_row('"unfinished;field')


if __name__ == "__main__":
    unittest.main()
